int vc4_get_cmdlist_and_shader_recs(struct drm_device *dev, struct vc4_exec_info *exec)
{
    struct vc4_dev *vc4 = to_vc4_dev(dev);
    struct vc4_bo *bo;
    void *cmdlist, *shaders;
    int ret;

    if (exec->cmdlist_size == 0 || exec->shader_recs_size == 0)
        return -EINVAL;

    cmdlist = kmalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!cmdlist)
        return -ENOMEM;

    shaders = kmalloc(exec->shader_recs_size, GFP_KERNEL);
    if (!shaders) {
        kfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->cmdlist_ptr), exec->cmdlist_size)) {
        kfree(cmdlist);
        kfree(shaders);
        return -EFAULT;
    }

    if (copy_from_user(shaders, u64_to_user_ptr(exec->shader_recs_ptr), exec->shader_recs_size)) {
        kfree(cmdlist);
        kfree(shaders);
        return -EFAULT;
    }

    ret = vc4_bo_create(dev, exec->cmdlist_size + exec->shader_recs_size, 0, &bo);
    if (ret) {
        kfree(cmdlist);
        kfree(shaders);
        return ret;
    }

    ret = vc4_bo_map(bo);
    if (ret) {
        kfree(cmdlist);
        kfree(shaders);
        vc4_bo_unref(bo);
        return ret;
    }

    memcpy(bo->vaddr, cmdlist, exec->cmdlist_size);
    memcpy(bo->vaddr + exec->cmdlist_size, shaders, exec->shader_recs_size);

    exec->cmdlist_bo = bo;
    exec->cmdlist = cmdlist;
    exec->shaders = shaders;

    if (!vc4_validate_cmdlist(cmdlist, exec->cmdlist_size) ||
        !vc4_validate_shader_recs(shaders, exec->shader_recs_size)) {
        kfree(cmdlist);
        kfree(shaders);
        vc4_bo_unref(bo);
        return -EINVAL;
    }

    if (vc4_wait_for_render_complete(dev))
        return -ETIMEDOUT;

    return 0;
}

int vc4_prepare_cmdlists_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    void *cmdlist_data;
    void *shader_records_data;
    struct drm_vc4_submit_cl *args = exec->args;
    int ret;

    if (args->shader_records_size > DRM_VC4_MAX_SHADER_RECORDS_SIZE ||
        args->command_list_size > DRM_VC4_MAX_CMDLIST_SIZE) {
        return -EINVAL;
    }

    cmdlist_data = kmalloc(args->command_list_size, GFP_KERNEL);
    if (!cmdlist_data)
        return -ENOMEM;

    shader_records_data = kmalloc(args->shader_records_size, GFP_KERNEL);
    if (!shader_records_data) {
        ret = -ENOMEM;
        goto fail_shader_records_alloc;
    }

    if (copy_from_user(cmdlist_data, u64_to_user_ptr(args->command_list), args->command_list_size)) {
        ret = -EFAULT;
        goto fail_copy_cmdlist;
    }

    if (copy_from_user(shader_records_data, u64_to_user_ptr(args->shader_records), args->shader_records_size)) {
        ret = -EFAULT;
        goto fail_copy_shader_records;
    }

    exec->cmdlist = cmdlist_data;
    exec->shader_records = shader_records_data;

    ret = vc4_bo_create(dev, args->bo_handle, &exec->bo);
    if (ret)
        goto fail_bo_create;

    exec->shader_record_ptr = exec->bo->vaddr + args->shader_record_offset;
    exec->uniforms_ptr = exec->bo->vaddr + args->uniforms_offset;
    exec->cmdlist_ptr = exec->bo->vaddr + args->command_list_offset;

    if (!exec->cmdlist_ptr || !exec->shader_record_ptr || !exec->uniforms_ptr) {
        ret = -EFAULT;
        goto fail_ptr_validation;
    }

    if (args->command_list_size != exec->cmdlist_size) {
        ret = -EINVAL;
        goto fail_cmdlist_size;
    }

    if (args->shader_records_size != exec->shader_records_size) {
        ret = -EINVAL;
        goto fail_shader_records_size;
    }

    vc4_wait_for_render_complete(dev, exec);

    return 0;

fail_shader_records_size:
fail_cmdlist_size:
fail_ptr_validation:
    vc4_bo_unref(exec->bo);
fail_bo_create:
fail_copy_shader_records:
    kfree(shader_records_data);
fail_copy_cmdlist:
    kfree(cmdlist_data);
fail_shader_records_alloc:
    return ret;
}

int vc4_prepare_exec(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    void *cmdlist, *shaders;
    size_t cmdlist_size, shaders_size;

    if (!exec->args->command_list_size || !exec->args->shader_records_size)
        return -EINVAL;

    cmdlist_size = exec->args->command_list_size;
    shaders_size = exec->args->shader_records_size;

    cmdlist = kmalloc(cmdlist_size, GFP_KERNEL);
    if (!cmdlist)
        return -ENOMEM;

    shaders = kmalloc(shaders_size, GFP_KERNEL);
    if (!shaders) {
        kfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->args->command_list), cmdlist_size)) {
        ret = -EFAULT;
        goto error_free;
    }

    if (copy_from_user(shaders, u64_to_user_ptr(exec->args->shader_records), shaders_size)) {
        ret = -EFAULT;
        goto error_free;
    }

    exec->cmdlist = cmdlist;
    exec->shaders = shaders;

    ret = vc4_validate_cmdlist(dev, exec);
    if (ret)
        goto error_free;

    ret = vc4_validate_shader_records(dev, exec);
    if (ret)
        goto error_free;

    ret = vc4_create_exec_bo(dev, exec);
    if (ret)
        goto error_free;

    ret = vc4_setup_shader_pointers(dev, exec);
    if (ret)
        goto error_free;

    ret = vc4_setup_uniforms(dev, exec);
    if (ret)
        goto error_free;

    drm_wait_for_vblank(dev, 0);

    return 0;

error_free:
    kfree(cmdlist);
    kfree(shaders);
    return ret;
}

int vc4_prepare_cmd_and_shader(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;

    /* Validate and allocate memory for command list */
    if (exec->cmdlist_size == 0) {
        return -EINVAL;
    }
    exec->cmdlist = kmalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!exec->cmdlist) {
        return -ENOMEM;
    }

    /* Validate and allocate memory for shader records */
    if (exec->shader_records_size == 0) {
        kfree(exec->cmdlist);
        return -EINVAL;
    }
    exec->shader_records = kmalloc(exec->shader_records_size, GFP_KERNEL);
    if (!exec->shader_records) {
        kfree(exec->cmdlist);
        return -ENOMEM;
    }

    /* Copy command list and shader records from user space */
    if (copy_from_user(exec->cmdlist, u64_to_user_ptr(exec->cmdlist_ptr), exec->cmdlist_size)) {
        ret = -EFAULT;
        goto error_free;
    }
    if (copy_from_user(exec->shader_records, u64_to_user_ptr(exec->shader_records_ptr), exec->shader_records_size)) {
        ret = -EFAULT;
        goto error_free;
    }

    /* Create buffer object for execution */
    ret = drm_gem_object_create(dev, exec->bo_size, &exec->bo);
    if (ret) {
        goto error_free;
    }

    /* Set up pointers for shader records and uniforms */
    exec->shader_record_ptr = exec->cmdlist + exec->cmdlist_shader_record_offset;
    exec->uniforms_ptr = exec->cmdlist + exec->cmdlist_uniforms_offset;

    /* Perform validation checks on command list and shader records */
    if (!validate_cmd_list(exec->cmdlist, exec->cmdlist_size) ||
        !validate_shader_records(exec->shader_records, exec->shader_records_size)) {
        ret = -EINVAL;
        goto error_free_bo;
    }

    /* Ensure any previous rendering operations are complete */
    if (vc4_wait_for_render_completion(dev)) {
        ret = -EBUSY;
        goto error_free_bo;
    }

    return 0;

error_free_bo:
    drm_gem_object_put(exec->bo);
error_free:
    kfree(exec->shader_records);
    kfree(exec->cmdlist);
    return ret;
}

int vc4_get_cmdlists_and_shader_recs(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;

    ret = validate_cmdlist_and_shader_sizes(dev, exec);
    if (ret)
        return ret;

    ret = allocate_cmdlist_and_shader_memory(exec);
    if (ret)
        return ret;

    ret = copy_user_data_to_cmdlist_and_shader(exec);
    if (ret)
        return ret;

    exec->bo = create_execution_buffer_object(dev, exec);
    if (!exec->bo)
        return -ENOMEM;

    setup_shader_record_pointers(exec);
    setup_uniform_pointers(exec);

    ret = validate_cmdlist_and_shader_records(exec);
    if (ret)
        return ret;

    ensure_rendering_completion(dev);

    return 0;
}
